const VL_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${o.mono?VL_M:VL_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}">${t}</text>`;
const VL_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const VL_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}" ${o.ex||''}/>`;
const VL_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return VL_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const VL_pl=(pts,col='#18213A',w=3)=>`<polyline points="${pts}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round"/>`;
const VL_sub=(a,b)=>`${a}<tspan baseline-shift="sub" font-size="70%">${b}</tspan>`;
const VL_X=(x,y,s,col)=>VL_L(x-s,y-s,x+s,y+s,col,7)+VL_L(x-s,y+s,x+s,y-s,col,7);
const VL_tick=(x,y,col)=>VL_pl(`${x-14},${y} ${x-4},${y+11} ${x+16},${y-12}`,col,6);
/* a row of bit cells: bits string, left x, top y, cell w and h */
const VL_bits=(bits,x,y,w=56,h=48,o={})=>[...bits].map((b,i)=>VL_box(x+i*(w+8),y,w,h,{r:8,fill:o.fill||'#FFFFFF',st:o.st||BLU,sw:3})+VL_T(x+i*(w+8)+w/2,y+h/2+10,b,{fs:o.fs||28,fw:800,a:'middle',mono:1,fill:o.col||'#18213A'})).join('');
const VL_xor=(cx,cy,r=18,col=BLU)=>`<circle cx="${cx}" cy="${cy}" r="${r}" fill="#FFFFFF" stroke="${col}" stroke-width="3"/>`+VL_L(cx-r+5,cy,cx+r-5,cy,col,3)+VL_L(cx,cy-r+5,cx,cy+r-5,col,3);
const VL_mux=(x,y,h=92,col=BLU)=>`<path d="M${x},${y} L${x+36},${y+16} L${x+36},${y+h-16} L${x},${y+h} Z" fill="#E7F5FF" stroke="${col}" stroke-width="3"/>`;
const VL_chip=(x,y,w,h,lab,col='#343A40')=>VL_box(x,y,w,h,{fill:col,st:col,r:10})+VL_T(x+w/2,y+h/2+9,lab,{fs:24,fw:800,a:'middle',fill:'#FFFFFF'});

